/* From Uiverse.io by rahilansari261 - Tags: form, register, loginform */
.__UIV_SCOPE__ .form {
  background-color: #15172b;
  border-radius: 20px;
  box-sizing: border-box;
  height: 500px;
  padding: 20px;
  width: 320px;
}

.__UIV_SCOPE__ .title {
  color: #eee;
  font-family: sans-serif;
  font-size: 36px;
  font-weight: 600;
  margin-top: 30px;
}

.__UIV_SCOPE__ .subtitle {
  color: #eee;
  font-family: sans-serif;
  font-size: 16px;
  font-weight: 600;
  margin-top: 10px;
}

.__UIV_SCOPE__ .input-container {
  height: 50px;
  position: relative;
  width: 100%;
}

.__UIV_SCOPE__ .ic1 {
  margin-top: 40px;
}

.__UIV_SCOPE__ .ic2 {
  margin-top: 30px;
}

.__UIV_SCOPE__ .input {
  background-color: #303245;
  border-radius: 12px;
  border: 0;
  box-sizing: border-box;
  color: #eee;
  font-size: 18px;
  height: 100%;
  outline: 0;
  padding: 4px 20px 0;
  width: 100%;
}

.__UIV_SCOPE__ .cut {
  background-color: #15172b;
  border-radius: 10px;
  height: 20px;
  left: 20px;
  position: absolute;
  top: -20px;
  transform: translateY(0);
  transition: transform 200ms;
  width: 76px;
}

.__UIV_SCOPE__ .cut-short {
  width: 50px;
}

.__UIV_SCOPE__ .iLabel {
  color: #65657b;
  font-family: sans-serif;
  left: 20px;
  line-height: 14px;
  pointer-events: none;
  position: absolute;
  transform-origin: 0 50%;
  transition: transform 200ms, color 200ms;
  top: 20px;
}

.__UIV_SCOPE__ .input:focus ~ .cut {
  transform: translateY(8px);
}

.__UIV_SCOPE__ .input:focus ~ .iLabel {
  transform: translateY(-30px) translateX(10px) scale(0.75);
}

.__UIV_SCOPE__ .input:not(:focus) ~ .iLabel {
  color: #808097;
}

.__UIV_SCOPE__ .input:focus ~ .iLabel {
  color: #dc2f55;
}

.__UIV_SCOPE__ .submit {
  background-color: #08d;
  border-radius: 12px;
  border: 0;
  box-sizing: border-box;
  color: #eee;
  cursor: pointer;
  font-size: 18px;
  height: 50px;
  margin-top: 38px;
  text-align: center;
  width: 100%;
}

.__UIV_SCOPE__ .submit:active {
  background-color: #06b;
}
